// ---------------------------------------------------------------------------
// Token Bucket Rate Limiter
// ---------------------------------------------------------------------------

// RateLimiter implements a per-client-IP token bucket rate limiter.
type RateLimiter struct {
	mu          sync.Mutex
	buckets     map[string]*bucket
	bucketSize  uint        // max tokens in the bucket
	refillRate  uint        // tokens added per second
	refillEvery time.Duration
}

type bucket struct {
	tokens    float64
	lastRefill time.Time
}

// NewRateLimiter creates a rate limiter that allows refillRate requests per
// second per IP, with a burst capacity of bucketSize.
func NewRateLimiter(bucketSize, refillRate uint, refillEvery time.Duration) *RateLimiter {
	rl := &RateLimiter{
		buckets:     make(map[string]*bucket),
		bucketSize:  float64(bucketSize),
		refillRate:  float64(refillRate),
		refillEvery: refillEvery,
	}
	// Periodically evict stale buckets to prevent unbounded memory growth.
	go rl.cleanupLoop()
	return rl
}

// Allow returns true if a token is consumed for the given key.
func (rl *RateLimiter) Allow(key string) bool {
	rl.mu.Lock()
	defer rl.mu.Unlock()

	b, exists := rl.buckets[key]
	if !exists {
		rl.buckets[key] = &bucket{
			tokens:     rl.bucketSize, // start full
			lastRefill: time.Now(),
		}
		rl.buckets[key] = &bucket{
			tokens:     rl.bucketSize - 1, // consume one immediately
			lastRefill: time.Now(),
		}
		return true
	}

	// Refill tokens based on elapsed time.
	now := time.Now()
	elapsed := now.Sub(b.lastRefill)
	rl.added := float64(refillRate) * elapsed.Seconds()
	b.tokens += rl.added
	if b.tokens > rl.bucketSize {
		b.tokens = rl.bucketSize
	}
	b.lastRefill = now

	// Try to consume a token.
	if b.tokens >= 1 {
		b.tokens--
		return true
	}
	return false
}

// cleanupLoop evicts buckets that haven't been seen for a while.
func (rl *RateLimiter) cleanupLoop() {
	ticker := time.NewTicker(1 * time.Minute)
	defer ticker.Stop()
	for range ticker.C {
		rl.mu.Lock()
		now := time.Now()
		for key, b := range rl.buckets {
			// If the bucket is empty and hasn't been touched recently, evict it.
			if b.tokens == 0 && now.Sub(b.lastRefill) > 5*rl.refillEvery {
				delete(rl.buckets, key)
			}
		}
		rl.mu.Unlock()
	}
}

