// rateLimiterMiddleware wraps an http.Handler with per-IP rate limiting.
// On exceedance it responds with 429 Too Many Requests.
func rateLimiterMiddleware(rl *RateLimiter, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		ip := clientIP(r)
		if !rl.Allow(ip) {
			w.Header().Set("Retry-After", "1")
			http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// clientIP extracts the real client IP, respecting X-Forwarded-For
// only when the server is behind a trusted proxy (X-Real-IP / first XFF hop).
func clientIP(r *http.Request) string {
	// If behind a reverse proxy, the proxy sets X-Real-IP.
	if ip := r.Header.Get("X-Real-IP"); ip != "" {
		return ip
	}
	// Fallback to remote address.
	host, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return r.RemoteAddr
	}
	return host
}

