import React, {
  useState,
  useEffect,
  useCallback,
  useMemo,
  useRef,
} from "react";

// ─── Types ───────────────────────────────────────────────────────────────────

interface TableItem {
  id: number;
  name: string;
  email: string;
  role: string;
  createdAt: string;
}

interface PaginatedResponse<T> {
  data: T[];
  total: number;
  page: number;
  pageSize: number;
}

interface SearchableTableProps {
  /** Base API endpoint, e.g. `/api/users` */
  endpoint: string;
  /** Column definitions for rendering */
  columns: ColumnConfig<TableItem>[];
  /** Initial page size (default: 10) */
  pageSize?: number;
  /** Debounce interval for search input in ms (default: 300) */
  searchDebounceMs?: number;
}

interface ColumnConfig<T> {
  key: keyof T;
  header: string;
  /** Optional render function for custom cell content */
  render?: (value: T[keyof T], row: T) => React.ReactNode;
}

// ─── Custom Hook: usePaginatedSearch ─────────────────────────────────────────

interface UsePaginatedSearchOptions {
  endpoint: string;
  pageSize: number;
  debounceMs: number;
}

interface UsePaginatedSearchReturn<T> {
  data: T[];
  loading: boolean;
  error: string | null;
  search: string;
  setSearch: (value: string) => void;
  page: number;
  setPage: (value: number) => void;
  total: number;
  totalPages: number;
  refetch: () => void;
}

function usePaginatedSearch<T>(
  options: UsePaginatedSearchOptions
): UsePaginatedSearchReturn<T> {
  const { endpoint, pageSize, debounceMs } = options;

  const [data, setData] = useState<T[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState<string>("");
  const [debouncedSearch, setDebouncedSearch] = useState<string>("");
  const [page, setPage] = useState<number>(1);
  const [total, setTotal] = useState<number>(0);
  const [fetchTrigger, setFetchTrigger] = useState<number>(0);

  const abortControllerRef = useRef<AbortController | null>(null);

  // Debounce the search input
  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(search);
      setPage(1); // Reset to first page on new search
    }, debounceMs);

    return () => clearTimeout(timer);
  }, [search, debounceMs]);

  // Fetch data when page, debounced search, or fetchTrigger changes
  useEffect(() => {
    // Cancel any in-flight request
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
    }

    const controller = new AbortController();
    abortControllerRef.current = controller;

    const fetchData = async () => {
      try {
        setLoading(true);
        setError(null);

        const params = new URLSearchParams({
          page: page.toString(),
          pageSize: pageSize.toString(),
          ...(debouncedSearch && { search: debouncedSearch }),
        });

        const response = await fetch(`${endpoint}?${params}`, {
          signal: controller.signal,
        });

        if (!response.ok) {
          const errorBody = await response.json().catch(() => null);
          throw new Error(
            errorBody?.message || `HTTP ${response.status}: ${response.statusText}`
          );
        }

        const result: PaginatedResponse<T> = await response.json();
        setData(result.data);
        setTotal(result.total);
      } catch (err: unknown) {
        if (err instanceof DOMException && err.name === "AbortError") {
          return; // Request was aborted — ignore
        }
        setError(err instanceof Error ? err.message : "An unexpected error occurred");
      } finally {
        if (!controller.signal.aborted) {
          setLoading(false);
        }
      }
    };

    fetchData();

    return () => {
      controller.abort();
    };
  }, [endpoint, page, pageSize, debouncedSearch, fetchTrigger]);

  const refetch = useCallback(() => {
    setFetchTrigger((prev) => prev + 1);
  }, []);

  const totalPages = Math.max(1, Math.ceil(total / pageSize));

  return {
    data,
    loading,
    error,
    search,
    setSearch,
    page,
    setPage,
    total,
    totalPages,
    refetch,
  };
}

