# Dijkstra's Algorithm in C++

## Implementation

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <climits>
#include <functional>

// Dijkstra's algorithm using a min-heap (priority queue)
// Returns a vector of shortest distances from 'source' to all reachable nodes.
// Nodes are indexed 0 .. numNodes-1.
std::vector<int> dijkstra(
    const std::vector<std::vector<std::pair<int, int>>>& graph,
    int source
) {
    int n = graph.size();
    std::vector<int> dist(n, INT_MAX);
    dist[source] = 0;

    // Min-heap: (distance, node).  std::greater gives us a min-heap.
    using P = std::pair<int, int>;
    std::priority_queue<P, std::vector<P>, std::greater<P>> pq;

    pq.push({0, source});

    while (!pq.empty()) {
        auto [d, u] = pq.top();
        pq.pop();

        // Lazy deletion: skip stale entries
        if (d > dist[u]) continue;

        for (const auto& [v, w] : graph[u]) {
            if (dist[u] != INT_MAX && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }

    return dist;
}

// ─────────────────────────────────────────────
// Example: a small weighted graph
//
//       4
//   0 ────── 1
//   |  |    /|
// 1|  2|  /  |3
//   |  | /   |
//   3 ── 2   4
//
//   Edges:
//     0→1 w=4,  0→2 w=1,  0→3 w=2
//     1→3 w=3,  2→1 w=2,  2→3 w=4
//
// ─────────────────────────────────────────────
int main() {
    const int N = 4;
    std::vector<std::vector<std::pair<int, int>>> graph(N);

    auto addEdge = [&](int u, int v, int w) {
        graph[u].push_back({v, w});
    };

    // Undirected graph (add both directions)
    addEdge(0, 1, 4);  addEdge(1, 0, 4);
    addEdge(0, 2, 1);  addEdge(2, 0, 1);
    addEdge(0, 3, 2);  addEdge(3, 0, 2);
    addEdge(1, 3, 3);  addEdge(3, 1, 3);
    addEdge(2, 1, 2);  addEdge(1, 2, 2);
    addEdge(2, 3, 4);  addEdge(3, 2, 4);

    int source = 0;
    std::vector<int> dist = dijkstra(graph, source);

    std::cout << "Shortest distances from node " << source << ":\n";
    for (int i = 0; i < N; ++i) {
        std::cout << "  " << source << " → " << i << " : ";
        if (dist[i] == INT_MAX)
            std::cout << "unreachable\n";
        else
            std::cout << dist[i] << "\n";
    }

    return 0;
}
