```

## `src/main.rs`

```rust
use std::collections::HashMap;
use std::fs;
use std::process;

use clap::Parser;

/// Count word frequencies in a text file and print the top N words.
#[derive(Parser)]
#[command(version, about, long_about = None)]
struct Cli {
    /// Path to the text file to analyze
    file: String,

    /// Number of top words to display
    #[arg(short = 'n', long, default_value_t = 10)]
    top: usize,

    /// Case-sensitive matching (default: case-insensitive)
    #[arg(short, long)]
    case_sensitive: bool,
}

fn main() {
    let cli = Cli::parse();

    if let Err(e) = run(cli) {
        eprintln!("Error: {e}");
        process::exit(1);
    }
}

fn run(cli: Cli) -> Result<(), Box<dyn std::error::Error>> {
    let contents = fs::read_to_string(&cli.file)
        .map_err(|e| format!("failed to read '{}': {e}", cli.file))?;

    let frequencies = count_words(&contents, cli.case_sensitive);

    // Sort by frequency (descending), then alphabetically (ascending) for ties
    let mut sorted: Vec<(&String, &usize)> = frequencies.iter().collect();
    sorted.sort_by(|a, b| b.1.cmp(a.1).then_with(|| a.0.cmp(b.0)));

    let top = sorted.into_iter().take(cli.top);

    // Find max count for aligned output
    let max_count = top
        .clone()
        .map(|(_, count)| *count)
        .max()
        .unwrap_or(0);
    let width = max_count.to_string().len();

    println!("{:<20} {:>width$}", "WORD", "COUNT");
    println!("{:<20} {:>width$}", "-".repeat(20), "-".repeat(width));

    for (word, count) in top {
        println!("{:<20} {:>width$}", word, count);
    }

    Ok(())
}

fn count_words(text: &str, case_sensitive: bool) -> HashMap<String, usize> {
    let mut frequencies: HashMap<String, usize> = HashMap::new();

    for word in extract_words(text, case_sensitive) {
        *frequencies.entry(word).or_insert(0) += 1;
    }

    frequencies
}

/// Splits text into words, stripping leading/trailing punctuation.
fn extract_words(text: &str, case_sensitive: bool) -> impl Iterator<Item = String> + '_ {
    text.split(|c: char| !c.is_alphanumeric())
        .filter(|s| !s.is_empty())
        .map(move |w| {
            if case_sensitive {
                w.to_string()
            } else {
                w.to_lowercase()
            }
        })
}
```

