### 2. Structure of Arrays (SoA) vs Array of Structures (AoS)

```c
typedef struct {
    float x, y, z;
    float vx, vy, vz;
} Particle;

// AoS layout in memory:
// [x0 y0 z0 vx0 vy0 vz0] [x1 y1 z1 vx1 vy1 vz1] ...

// SoA layout in memory:
// [x0 x1 x2 x3 ...] [y0 y1 y2 y3 ...] [z0 z1 z2 z3 ...]
// [vx0 vx1 vx2 ...] [vy0 vy1 vy2 ...] [vz0 vz1 vz2 ...]
```

```c
// AoS — if you only need to update positions, you load the
// entire 24-byte struct per particle, wasting bandwidth on velocities.
void update_positions_aos(Particle *p, int n, float dt) {
    for (int i = 0; i < n; i++) {
        p[i].x += p[i].vx * dt;
        p[i].y += p[i].vy * dt;
        p[i].z += p[i].vz * dt;
    }
}

// SoA — contiguous access to only the fields you need.
// Better spatial locality, enables vectorization (SIMD),
// and reduces cache line pollution.
void update_positions_soa(float *xs, float *ys, float *zs,
                          float *vxs, float *vys, float *vzs,
                          int n, float dt) {
    for (int i = 0; i < n; i++) {
        xs[i] += vxs[i] * dt;
        ys[i] += vys[i] * dt;
        zs[i] += vzs[i] * dt;
    }
}
```

